from __future__ import annotations
PATHS={
'/api/auth/register':['post'],'/api/auth/login':['post'],'/api/events':['get','post'],'/api/events/{eventId}':['get','put','delete'],'/api/events/{eventId}/budget':['get'],'/api/events/{eventId}/tasks':['get','post'],'/api/events/{eventId}/tasks/{taskId}':['get','put','delete'],'/api/events/{eventId}/guests':['get','post'],'/api/events/{eventId}/guests/{guestId}':['get','put','delete'],'/api/events/{eventId}/budget-categories':['get','post'],'/api/events/{eventId}/budget-categories/{categoryId}':['get','put','delete'],'/api/events/{eventId}/budget-categories/{categoryId}/budget':['get'],'/api/events/{eventId}/budget-categories/{categoryId}/expenses':['get','post'],'/api/events/{eventId}/budget-categories/{categoryId}/expenses/{expenseId}':['get','put','delete'],'/api/events/{eventId}/schedule-items':['get','post'],'/api/events/{eventId}/schedule-items/{scheduleItemId}':['get','put','delete'],'/api/events/{eventId}/vendors':['get','post'],'/api/events/{eventId}/vendors/{vendorId}':['get','put','delete'],'/api/events/{eventId}/vendors/{vendorId}/payments':['get','post'],'/api/events/{eventId}/vendors/{vendorId}/payments/{paymentId}':['get','put','delete'],'/api/notifications':['get'],'/api/notifications/{notificationId}':['get','put','delete'],'/api/events/{eventId}/audit-logs':['get'],'/openapi.json':['get'],'/docs':['get']}
def build_openapi()->dict:
 paths={p:{m:{'responses':{'200':{'description':'Success'},'401':{'$ref':'#/components/responses/Error'}},**({} if p.startswith('/api/auth') else {'security':[{'bearerAuth':[]}]})} for m in methods} for p,methods in PATHS.items()}
 return {'openapi':'3.0.3','info':{'title':'EventForge API','version':'1.0.0'},'paths':paths,'components':{'securitySchemes':{'bearerAuth':{'type':'http','scheme':'bearer','bearerFormat':'JWT'}},'schemas':{'Money':{'type':'string','pattern':'^-?\\d+\\.\\d{2}$'},'Error':{'type':'object','required':['timestamp','status','error','message','path']}},'responses':{'Error':{'description':'Error response','content':{'application/json':{'schema':{'$ref':'#/components/schemas/Error'}}}}}}}
